<?php
if(!defined('REDFOX_SKIP_BOTAPI_ROUTER'))define('REDFOX_SKIP_BOTAPI_ROUTER',true);require_once __DIR__.'/../lib/Security.php';redfox_secure_session_start();require_once __DIR__.'/../config.php';require_once __DIR__.'/lib/icons.php';$q=$pdo->prepare('SELECT * FROM admin WHERE username=? LIMIT 1');$q->execute([$_SESSION['user']??'']);$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a){header('Location:login.php');exit;}if(($a['rule']??'')!=='administrator'){http_response_code(403);exit;}$flash='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$id=(string)($_POST['order_id']??'');$act=(string)($_POST['action']??'');if($act==='resolve'){$q=$pdo->prepare("UPDATE payment_effects SET status='completed',last_error='resolved manually by administrator',updated_at=? WHERE order_id=? AND status='needs_reconcile'");$q->execute([time(),$id]);$pdo->prepare('INSERT INTO audit_log(admin_user,action,entity,details,ip,created_at) VALUES(?,?,?,?,?,?)')->execute([$a['username'],'payment_effect.resolve',$id,'manual reconciliation',redfox_client_ip(),date('c')]);$flash=$q->rowCount()?'تطبیق ثبت شد.':'عملیات قابل تطبیق نیست.';}}
try{$rows=$pdo->query("SELECT pe.*,p.id_user,p.price,p.Payment_Method,p.payment_Status FROM payment_effects pe LEFT JOIN Payment_report p ON p.id_order=pe.order_id ORDER BY pe.updated_at DESC LIMIT 500")->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$rows=[];$flash='Migration 005 اجرا نشده است.';}?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>تطبیق پرداخت</title><link rel="stylesheet" href="css/theme.css"></head><body><section id="container"><?php include'header.php';?><section id="main-content"><div class="wrapper"><div class="page-head"><h1 class="page-head__title">تطبیق اثرات پرداخت</h1><div class="page-head__sub">پرداخت needs_reconcile را هرگز بدون بررسی کیف پول، سرویس و درگاه تکمیل نکنید</div></div><?php if($flash):?><div class="card"><?=htmlspecialchars($flash)?></div><?php endif;?><div class="card"><div class="table-wrap"><table class="app-table"><tr><th>سفارش</th><th>کاربر/مبلغ</th><th>درگاه</th><th>وضعیت فاکتور</th><th>وضعیت اثرات</th><th>خطا</th><th></th></tr><?php foreach($rows as$r):?><tr><td><code><?=htmlspecialchars($r['order_id'])?></code></td><td><?=$r['id_user']?> / <?=number_format((int)$r['price'])?></td><td><?=htmlspecialchars($r['Payment_Method']??$r['source'])?></td><td><?=$r['payment_Status']?></td><td><span class="badge"><?=$r['status']?></span></td><td><?=htmlspecialchars((string)$r['last_error'])?></td><td><?php if($r['status']==='needs_reconcile'):?><form method="post"><input type="hidden" name="order_id" value="<?=htmlspecialchars($r['order_id'])?>"><button class="btn btn-sm btn-success" name="action" value="resolve" onclick="return confirm('فقط پس از بررسی دستی همه اثرات پرداخت، تکمیل شود؟')">تطبیق شد</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></div></div></section></section></body></html>
